import { createChart, removeChart } from '../test/ut/core/utHelper';
import { EChartsType } from '../src/echarts.all';

function getProgressEls(chart: EChartsType): { z2: number }[] {
    const view = (chart as any)._chartsViews[0];
    return view._progressEls || [];
}

function renderGauge(min: number, max: number, values: number[]): { z2: number }[] {
    chart = createChart();
    chart.setOption({
        series: [{
            type: 'gauge',
            min: min,
            max: max,
            progress: {
                show: true,
                overlap: true,
                width: 10
            },
            pointer: {
                show: false
            },
            data: values.map(function (value) {
                return { value: value };
            })
        }]
    });
    return getProgressEls(chart);
}

let chart: EChartsType;

describe('gauge-negative-z2', function () {

    afterEach(function () {
        chart && removeChart(chart);
        chart = null;
    });

    it('progress z2 stays non-negative when max is negative', function () {
        const progressEls = renderGauge(-100, -10, [-80, -30, -15]);
        expect(progressEls.length).toBe(3);
        progressEls.forEach(function (el) {
            expect(el.z2).toBeGreaterThanOrEqual(0);
            expect(el.z2).toBeLessThanOrEqual(100);
        });
        // z2 is linearly mapped from [min, max] to [100, 0]:
        // smaller value gets a larger z2 (drawn on top among overlaps is fine as long as valid).
        expect(progressEls[0].z2).toBeCloseTo(100 - (-80 - -100) / (-10 - -100) * 100, 5);
        expect(progressEls[1].z2).toBeCloseTo(100 - (-30 - -100) / (-10 - -100) * 100, 5);
        expect(progressEls[2].z2).toBeCloseTo(100 - (-15 - -100) / (-10 - -100) * 100, 5);
    });

    it('positive range gauges keep valid z2 ordering', function () {
        const progressEls = renderGauge(0, 100, [20, 60, 90]);
        expect(progressEls.length).toBe(3);
        progressEls.forEach(function (el) {
            expect(el.z2).toBeGreaterThanOrEqual(0);
            expect(el.z2).toBeLessThanOrEqual(100);
        });
        expect(progressEls[0].z2).toBeCloseTo(80, 5);
        expect(progressEls[1].z2).toBeCloseTo(40, 5);
        expect(progressEls[2].z2).toBeCloseTo(10, 5);
    });
});

